mapper.update:
UPDATE chat_room SET restricted_until =
'9999-12-31 23:59:59' NOW() + INTERVAL #{days} DAY
WHERE id = #{roomId}

mapper.select:
SELECT
r.status = #{status}
ORDER BY COALESCE(r.last_message_at, r.created_at) DESC LIMIT 100

SELECT * FROM (
    SELECT id, room_id, sender_type, sender_id, content, created_at
    FROM chat_message
    WHERE room_id = #{roomId}

        AND id < #{beforeId}

    ORDER BY id DESC
    LIMIT #{size}
) recent
ORDER BY id
